{
  "name": "ERASynth射频信号发生器",
  "name_en": "ERASynth RF Signal Generator",
  "manufacturer": "",
  "description": "一款实验室用射频频率合成/信号发生器，可输出设定频率与功率的射频信号，常作为本振或测试信号源使用。适用于射频与微波实验中的链路测试、器件表征和系统调试；部分相关功能表明设备还带有参考源设置及 Wi‑Fi 模块控制能力。",
  "description_en": "A laboratory RF frequency synthesizer and signal generator that outputs RF signals at specified frequency and power levels. It is commonly used as a local oscillator or test source in RF and microwave experiments for link testing, device characterization, and system debugging; available functions also indicate reference source configuration and control of an onboard Wi-Fi module.",
  "tag_hints": [
    "RF signal generation",
    "frequency synthesizer",
    "local oscillator",
    "microwave source",
    "RF testing",
    "serial communication",
    "Wi-Fi module"
  ],
  "actions": [
    {
      "action_name": "auto-esp8266_upload_mode",
      "description": "启用 ESP8266 上传模式",
      "description_en": "Enable ESP8266 upload mode"
    },
    {
      "action_name": "auto-factory_reset",
      "description": "恢复出厂设置",
      "description_en": "Restore factory settings"
    },
    {
      "action_name": "auto-off",
      "description": "关闭射频输出",
      "description_en": "Turn off the RF output"
    },
    {
      "action_name": "auto-on",
      "description": "打开射频输出",
      "description_en": "Turn on the RF output"
    },
    {
      "action_name": "auto-open_port",
      "description": "打开设备串口连接",
      "description_en": "Open the serial connection to the device"
    },
    {
      "action_name": "auto-preset",
      "description": "将设备预置到已知设置",
      "description_en": "Preset the device to known settings"
    },
    {
      "action_name": "auto-run_self_test",
      "description": "在支持的机型上运行自检",
      "description_en": "Run the self-test on supported models"
    },
    {
      "action_name": "auto-wifi_off",
      "description": "关闭 Wi‑Fi 模块",
      "description_en": "Turn off the Wi-Fi module"
    },
    {
      "action_name": "auto-wifi_on",
      "description": "打开 Wi‑Fi 模块",
      "description_en": "Turn on the Wi-Fi module"
    },
    {
      "action_name": "auto-print_serial_ports",
      "description": "列出可用串口",
      "description_en": "List available serial ports"
    },
    {
      "action_name": "auto-get_configuration",
      "description": "获取设备配置参数",
      "description_en": "Get the device configuration"
    },
    {
      "action_name": "auto-get_diagnostic_status",
      "description": "获取设备诊断状态",
      "description_en": "Get the device diagnostic status"
    }
  ]
}

